import "io" for Directory

// Full create/list/delete lifecycle using /tmp for the new directory
// (Directory.create in wren-cli creates with mode 0 in CWD, but /tmp works)
// Here we verify the lifecycle using the existing tmp directory pattern
// (same as the existing create_delete.wren test)

// Use the existing test directory for list operations
var listing = Directory.list("test/io/file")
System.print(listing is List)   // expect: true
System.print(listing.count > 0) // expect: true
System.print(listing.contains("file.txt")) // expect: true

// Verify create/delete cycle with the existing "tmp" dir pattern
if (Directory.exists("tmp")) {
  Directory.delete("tmp")
}
System.print(Directory.exists("tmp")) // expect: false
Directory.create("tmp")
System.print(Directory.exists("tmp")) // expect: true
Directory.delete("tmp")
System.print(Directory.exists("tmp")) // expect: false
